// posts_queue.csv から次の投稿を取得
const csvText = $input.item.binary.data.data.toString('utf-8');
const lines = csvText.split('\n');
const headers = lines[0].split(',').map(h => h.trim());

let nextPost = null;
for (let i = 1; i < lines.length; i++) {
  if (!lines[i].trim()) continue;
  const values = lines[i].split(',').map(v => v.trim());
  const record = {};
  headers.forEach((h, idx) => record[h] = values[idx]);

  if (record.status === 'scheduled') {
    nextPost = record;
    break;
  }
}

if (!nextPost) {
  return { success: false, message: 'No scheduled posts found' };
}

return {
  post_id: nextPost.id,
  content_id: nextPost.content_id,
  scheduled: nextPost.scheduled,
  url: nextPost.url
};

// DEV_RIO_705 Threads×楽天。qa_status=PASS 時のみ楽天リプライを生成・自動投稿。
// ============================================================
// 投稿キュー（定数）
// ============================================================
// マスターは products/revenue-intelligence-os/data/posts_queue.csv（スケジュール）
// と products/revenue-intelligence-os/data/threads_posts.csv（本文）。
// 当初は Load Posts Queue（readBinaryFile）でローカルCSVを読む設計だったが、
// n8n Cloud はローカルファイルパスを読めないため、Link Library と同じ方式で
// このCode ノードに直接転記する（CSVがマスター、ここは写し）。
// 転記手順: CSVを更新 → 下の配列に同内容を追加 → Save → 手動テスト実行。
// 実行日（JST）に一致する date の投稿のみを対象にする。
const POSTS_QUEUE = [
  { date: '2026-08-04', content_id: 'post_4', threads_post: "スタッフを褒めてもらえた口コミへの返信例です。--- 温かいクチコミをいただきありがとうございます。スタッフの対応にご満足いただけたとのこと、本人をはじめスタッフ全員の励みになります。お客様に「また来たい」と感じていただけるよう、日々の接客を大切にしております。またのご来店をスタッフ一同お待ちしております。--- 型は「感謝→褒められた点に触れる→日頃の姿勢→再来店の一言」。口コミで褒められた内容に1行触れるだけで、コピペ感はかなり消えます。" },
  { date: '2026-08-05', content_id: 'post_5', threads_post: "事実と違う（と感じる）口コミが来たとき、「そのような事実はありません」と書きたくなりますよね。その気持ちは、すごくわかります。でも強い否定の返信は、書いた本人よりも「これから行くか迷っている人」に読まれます。おすすめは、否定ではなく確認の姿勢。「詳しい状況を確認したいので、よろしければ直接ご連絡いただけますか」この形なら、読んだ第三者にも誠実さが伝わりやすくなります。" },
  { date: '2026-08-06', content_id: 'post_6', threads_post: "口コミ返信で、やってしまいがちなNGを3つ。1. テンプレの[店舗名]を書き換え忘れたまま投稿 2. ネガティブ口コミに「事実と異なります」と強く否定 3. 「また口コミ書いてください」と投稿をお願いする → 金品や特典で口コミを誘導するのはGoogleの規約違反になります返信は250〜400文字くらいが読まれやすい目安。凝った文章より、「ちゃんと反応しているお店」だと伝わることが大事です。" },
  { date: '2026-08-07', content_id: 'post_8', threads_post: "★5でも★1でもない、★3の口コミ。実はこれが一番返信に困るという声をよく聞きます。「悪くはないけど特別でもない」という温度の文章に、無理やり満点の感謝を書くと嘘っぽくなるし、かといって謝るような内容でもありません。私がおすすめしているのは、書かれている内容から一つだけ具体的に拾って返すこと。「メニューの種類についてのご意見、今後の参考にさせていただきます」くらいの温度で十分だと思います。★3の口コミ、皆さんはどう返していますか。" },
  { date: '2026-08-08', content_id: 'post_9', threads_post: "「メニューが少ない」「駐車場が停めにくい」など、辛口だけど具体的な指摘をくれる口コミへの返信例です。--- 貴重なご意見をありがとうございます。◯◯の点でご不便をおかけし申し訳ございませんでした。いただいたご指摘は今後の改善の参考にさせていただきます。より良いお店づくりに努めてまいります。--- 型は「感謝→指摘箇所への言及→改善への意欲→今後の一言」。反論せず、指摘の中身に一度触れるのがポイントです。感情的な低評価より、こういう具体的な指摘のほうが実は改善のヒントになります。" },
  { date: '2026-08-10', content_id: 'post_10', threads_post: "繁忙期に口コミ返信が後回しになって、気づいたら1ヶ月分たまっている。こういう状態になったことのあるオーナーさん、多いと思います。私も繁忙期に3週間分を溜めたことがあります。ただ、まとめて返信するときも「お返事が大変遅くなり申し訳ございません」の一言を最初に添えるだけで、印象はかなり変わります。全部を完璧に返そうとせず、直近の分から手をつけるくらいでちょうどいいと思っています。皆さんは口コミ返信、どのタイミングでまとめてやっていますか。" },
  { date: '2026-08-11', content_id: 'post_11', threads_post: "同じ「ありがとうございます」でも、業種によって返信のトーンは少し変えたほうが伝わります。美容室なら「担当した◯◯も大変喜んでおります」など施術者個人への言及。飲食店なら「またあの一品をお出しできる日を楽しみにしております」などメニュー名への言及。整体院なら「お身体の調子が少しでも楽になっていましたら幸いです」など体調への言及。丁寧さは同じでも、業種ごとに「何に触れるか」を変えるだけで、テンプレっぽさがかなり減ります。" },
  { date: '2026-08-12', content_id: 'post_12', threads_post: "何年も通ってくれている常連さんが、久しぶりに口コミを書いてくれることがあります。こういうとき、いつもの返信テンプレをそのまま使うと、なんだか味気ない気がしてしまいます。かといって、常連さんだと分かる内容を書くのは個人情報的に微妙です。私がやっているのは「いつもご利用いただきありがとうございます」の一言を最初に足すことだけです。それだけで、初めての方への返信とは違う温度になります。常連さんの口コミ、皆さんはどう返していますか。" },
  { date: '2026-08-13', content_id: 'post_13', threads_post: "予約が反映されていなかった、機器の不具合で対応が遅れた…お店側に非がある口コミへの返信例です。--- この度はご予約の確認不足によりご迷惑をおかけし、誠に申し訳ございませんでした。原因を確認し、再発防止のため予約管理の見直しを行っております。ご不便をおかけしましたこと、重ねてお詫び申し上げます。またお越しいただける機会がございましたら、精一杯対応させていただきます。--- ポイントは、原因を曖昧にせず「見直しをしている」まで書くこと。謝罪だけで終わると、読んだ人には他人事に見えてしまいます。" },
  { date: '2026-08-14', content_id: 'post_14', threads_post: "口コミ返信テンプレートとは別に、もう一つ作っているものがあります。Google投稿・口コミ返信・SNS投稿、この3つを毎週ゼロから考えるのは正直しんどいです。ChatGPTに読み込ませるだけで7日分の投稿文一式を30分で作れるキットを用意しました。テンプレートではなく「毎週の運用の型」をまるごと渡すイメージです。美容室・飲食店・整体院での運用を想定しています。¥1980で公開中です。気になる方はプロフィールからどうぞ。" }
];
const now = new Date();
const jstNow = new Date(now.getTime() + 9 * 60 * 60 * 1000);
const todayStr = jstNow.toISOString().slice(0, 10);
const todayPost = POSTS_QUEUE.find(p => p.date === todayStr);
if (!todayPost) {
  return [{ json: {
    content_id: null,
    threads_post: '',
    qa_status: 'SKIP',
    skip_reason: 'no_post_scheduled_for_' + todayStr,
    platform: 'threads',
    action_type: 'post_rakuten_reply'
  } }];
}
return [{ json: {
  content_id: todayPost.content_id,
  threads_post: todayPost.threads_post,
  qa_status: 'PASS',
  platform: 'threads',
  action_type: 'post_rakuten_reply'
} }];

// ============================================================
// 楽天アフィリエイト リンクライブラリ（定数）
// ============================================================
// マスターは products/revenue-intelligence-os/data/rakuten_link_library.csv。
// n8nクラウドはローカルファイルを読めないため、CSVの status=active の行を
// この LINK_LIBRARY 定数へ手で転記して運用する（CSVがマスター、ここは写し）。
// 転記手順: CSVに行追加 → 下の配列に同内容を追加 → Save → 手動テスト実行。
// ⚠ affiliate_url はゆうさんが楽天アフィリ管理画面で発行した実URLのみ。
//   手打ち・推測・生成したURLをここに書くことは禁止（リンク捏造ゼロ）。
// 記入例（ダミー・コメントのみ。実URLではない）:
// { id: 'RKT-001', genre: 'kitchen', aliases: ['キッチン', '調理器具'],
//   product_name: '（例）フライパン28cm',
//   affiliate_url: 'https://hb.afl.rakuten.co.jp/hgc/XXXXXXXX/?pc=DUMMY-DO-NOT-USE',
//   pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' }
const LINK_LIBRARY = [
  // CSV（rakuten_link_library.csv）からの転記。2026-08-02 発行分。
  { id: 'RKT-001', genre: 'photo_gear', aliases: ['撮影機材', 'リングライト', 'スマホ撮影', 'ライト', '写真', 'photo', 'lighting'],
    product_name: 'リングライト 三脚タイプ スマホスタンド 10インチ',
    affiliate_url: 'https://a.r10.to/hkmJqO',
    pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' },
  { id: 'RKT-002', genre: 'store_signage', aliases: ['看板', 'A型看板', 'ブラックボード', '店頭看板', '黒板', 'signage'],
    product_name: 'A型看板 ブラックボード 両面 38×78cm 木製',
    affiliate_url: 'https://a.r10.to/T3YbFn',
    pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' },
  { id: 'RKT-003', genre: 'marketing_book', aliases: ['集客本', 'マーケティング本', '書籍', '本', 'book', 'sns集客'],
    product_name: '店舗やサロンのためのInstagram集客・販促の教科書',
    affiliate_url: 'https://a.r10.to/hgtsW1',
    pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' },
  { id: 'RKT-004', genre: 'cleaning_supplies', aliases: ['清掃', '掃除', '衛生用品', 'ペーパータオル', '清潔', 'cleaning'],
    product_name: '業務用ペーパータオル 200枚×35パック',
    affiliate_url: 'https://a.r10.to/hRG9xn',
    pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' }
];
const active = LINK_LIBRARY.filter(e => e && e.status === 'active' && e.affiliate_url);
const genre_keys = [...new Set(active.map(e => String(e.genre || '').trim()).filter(Boolean))];
const i = $input.first().json;
return [{ json: { ...i, link_library: active, genre_keys } }];

// 楽天リプライ下書きの生成プロンプトを Anthropic body オブジェクトとして組み立てる。
// product_genre はリンクライブラリのジャンルキーから選ばせ、後段の照合を確実にする。
const i = $input.first().json;
const post = String(i.threads_post || '').slice(0, 300);
const genres = (i.genre_keys && i.genre_keys.length) ? i.genre_keys.join(' / ') : '(登録なし)';
const prompt = `以下のThreads投稿に自然に続く、商品紹介リプライの下書きを2案。\n\n投稿: ${post}\n\n条件:\n- 各60字以内、日本語。\n- 押し売り感なし。\n- 実在商品を断定しない。特定の商品名・URLは書かない。\n- product_genre は次のジャンルキーから最も合うものを1つだけ選ぶ: ${genres}。どれも合わない場合は "none" とする。\n- 出力は次のJSON配列のみ（前後に説明・コードブロック記号を付けない）:\n[{"reply":"string","product_genre":"string"}]`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 512,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, anthropic_body } }];

// Claude応答をパース。捏造しない。リンクは後段の Match Rakuten Link でのみ付与される。
const input = $input.first().json;
const ctx = $('Collect Inputs').first().json;
let replies = [];
let parse_error = null;
if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\[[\s\S]*\]/);
    replies = JSON.parse(match ? match[0] : cleaned);
    if (!Array.isArray(replies) || replies.length === 0) throw new Error('replies missing/empty');
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}
if (parse_error) replies = [{ reply: '（AI応答の取得/解析に失敗。手動で作成してください）', product_genre: 'manual' }];
const enriched = replies.map((r) => ({
  content_id: ctx.content_id,
  reply: r.reply ?? '',
  product_genre: r.product_genre ?? '',
  draft_error: parse_error
}));
return enriched.map(item => ({ json: item }));

// リンクライブラリ照合。ゆうさん発行の実リンクがある genre の下書きだけ投稿対象にする。
// マッチしない下書きは link_matched=false → 後段の Link Gate で NO_LINK_SKIP へ。
// これにより「リンクなし・プレースホルダーのままの投稿」は構造的に発生しない。
const lib = $('Link Library').first().json.link_library || [];
const norm = (s) => String(s || '').trim().toLowerCase();
const items = $input.all();
return items.map((item) => {
  const d = item.json;
  const g = norm(d.product_genre);
  let entry = null;
  if (g && g !== 'none' && g !== 'manual') {
    entry = lib.find(e => norm(e.genre) === g || (Array.isArray(e.aliases) && e.aliases.some(a => norm(a) === g))) || null;
  }
  if (!entry) {
    return { json: { ...d, link_matched: false } };
  }
  // 投稿文には必ず #PR 表記を含める（ステマ規制対応。景品表示法ガイドライン上、
  // 「広告」「PR」「#PR」等の簡潔な表示で法的要件を満たせるため短縮表記を採用）。
  // pr_note はライブラリ側の運用メモとして残すが、投稿文の組み立てには使わない。
  const pr_line = '#PR';
  const final_reply = [String(d.reply || ''), '', pr_line, String(entry.affiliate_url)].join('\n');
  // Threads API へは改行・記号入りテキストをクエリではなく JSON body で送る（400 Bad request 対策）。
  // Anthropic 呼び出しと同じ「Code ノードで body を組み立てて jsonBody で渡す」パターン。
  const threads_body = { media_type: 'TEXT', text: final_reply };
  return { json: {
    ...d,
    link_matched: true,
    link_id: entry.id ?? null,
    product_name: entry.product_name ?? null,
    affiliate_url: entry.affiliate_url,
    final_reply,
    threads_body
  } };
});

// Publish 用の body を組み立てる（creation_id もクエリではなく JSON body で送る堅牢化）。
// コンテナ作成が失敗した item は id が無く creation_id='' となり、Publish が失敗して
// Aggregate Results で POST_FAILED として集計される（従来と同じ挙動）。
const items = $input.all();
return items.map((item) => {
  const j = item.json;
  return { json: { ...j, publish_body: { creation_id: String(j.id || '') } } };
});

// Threads API 応答を集約。
const items = $input.all();
const ctx = $('Collect Inputs').first().json;
const results = items.map((item, idx) => {
  const publish = item.json;
  const posted = !!(publish && publish.id && !publish.error);
  return {
    content_id: ctx.content_id,
    thread_id: posted ? publish.id : null,
    state: posted ? 'POSTED' : 'POST_FAILED',
    published: posted,
    posted_at: posted ? new Date().toISOString() : null,
    error: publish && publish.error ? JSON.stringify(publish.error).slice(0, 300) : null
  };
});
return [{ json: { results, posted_count: results.filter(r => r.published).length, failed_count: results.filter(r => !r.published).length } }];

// リンクライブラリに該当 genre の active リンクが無いため、この下書きは投稿しない。
// リンクなし・プレースホルダーのままの投稿を出さないための恒久ガード。
const items = $input.all();
const results = items.map((item) => ({
  content_id: item.json.content_id,
  reply: item.json.reply,
  product_genre: item.json.product_genre,
  state: 'NO_LINK_SKIP',
  published: false,
  note: 'ライブラリに genre 一致の active リンクが無いためスキップ。rakuten_link_library.csv に登録し Link Library ノードへ転記すれば投稿対象になる。'
}));
return [{ json: { state: 'NO_LINK_SKIP', skipped_count: results.length, results } }];

// QAゲート不通過。リプライ生成をスキップ。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id,
  skipped: true,
  qa_status: i.qa_status,
  state: 'SKIPPED_NOT_PASS',
  published: false,
  note: 'qa_status が PASS ではないため Threads楽天リプライ生成をスキップ。'
} }];
